 obs=list(csv.DictReader((OUT/'observations/eilers2019-jiao2021.csv').open()));p=load_model();R=np.array([float(x['R_kpc'])for x in obs]);q=np.c_[R,0*R,0*R];y=np.array([float(x['vc_km_s'])for x in obs]);vm=np.array([np.sqrt(-R*agama.Potential(*p[:3]).force(q)[:,0]),np.sqrt(-R*agama.Potential(*p).force(q)[:,0])]);sm=np.array([float(x['stat_minus_km_s'])for x in obs]);sp=np.array([float(x['stat_plus_km_s'])for x in obs]);sig=(sm+sp)/2;sys=np.array([float(x['jiao_fractional_systematic'])for x in obs])*y;diag=sig**2+sys**2;C=np.diag(diag)+np.outer(.02*y,.02*y);summaries=[];rows=[]
